#pragma once
#include "ksScheduledTimerService.h"
#include "ksStateUiDomainBindings.h"
namespace ks {namespace scheduledTimerBindings {
inline StateUiDomainTransfer repeat(const StateCentralActionsService&s,unsigned index=0){using Q=StateCentralActionsService::Request;using F=StateCentralActionsService::Family;const auto&n=s.coordinator().node(index);StateUiDomainTransfer out;for(unsigned j=0;j<n.children;++j){const auto&e=n.outcomes[j];if(e.node!=255){out.then(repeat(s,e.node));continue;}if(!e.result.outcome.value)throw std::logic_error("Missing timer repeat native outcome");const auto&o=s.outcome(e.result.outcome.value-1);if(o.request==Q::RepeatArm)out.expression=fieldExpressionBindings::full(ScheduledTimerCoordinator::binding(ScheduledTimerCoordinator::Action(o.input.action)));switch(o.family){case F::Field:if(o.request==Q::UiRefresh)out.then(stateUiRefreshDomainTransfer(s.field(o.slot)));else if(o.request==Q::Notify)out.then(stateSceneDomainTransfer(s.field(o.slot)));else if(o.request==Q::NameInsertDigit||o.request==Q::NameToggle||o.request==Q::NameInsertSpace||o.request==Q::NameClearSuffix||o.request==Q::SceneDecrement||o.request==Q::SceneIncrement)out.then(stateSceneEditDomainTransfer(s.field(o.slot)));else out.then(stateFieldDomainTransfer(s.field(o.slot)));break;case F::Screen:out.then(stateScreenDomainTransfer(s.screen(o.slot)));break;case F::Apply:out.expression.then(fieldExpressionBindings::applied(&s.apply()));out.activation={true,s.apply().cached()};break;case F::Heavy:std::visit([&](const auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,StateProgramBrowserService>)out.then(stateProgramBrowserDomainTransfer(t));else throw std::logic_error("Unexpected timer repeat heavy action");},s.heavy());break;case F::Probe:case F::Repeat:break;default:throw std::logic_error("Unexpected timer repeat native family");}}return out;}
inline PanelActivationTransfer statusActivation(const StateStatusService&s,unsigned index=0){using K=StateStatusService::Kind;const auto&f=s.outcome(index);if(f.kind==K::Compare||(f.kind==K::Part&&f.single))return{true,uint8_t(f.task.program()>>8)};if(f.kind==K::Part&&f.active||f.kind==K::Tick&&f.route==StateStatusService::Route::Part)return statusActivation(s,f.child);return{};}
inline StateUiDomainTransfer callback(const ScheduledTimerService&s){StateUiDomainTransfer out;std::visit([&](const auto&c){using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,std::monostate>)throw std::logic_error("Missing completed timer functional callback");else if constexpr(std::is_same_v<T,StateFieldService>)out=stateFieldDomainTransfer(c);else if constexpr(std::is_same_v<T,ScheduledTimerService::Notice>){if(!c.ui)throw std::logic_error("Missing notice UI functional outcome");out=stateUiRefreshDomainTransfer(*c.ui);}else if constexpr(std::is_same_v<T,StateCentralActionsService>)out=repeat(c);else if constexpr(std::is_same_v<T,StateProgramBrowserService>)out=stateProgramBrowserDomainTransfer(c);else if constexpr(std::is_same_v<T,StateStatusService>){out.expression=fieldExpressionBindings::full(0x55e2);out.activation=statusActivation(c);}},s.child());return out;}
}
inline StateUiDomainTransfer scheduledTimerDomainTransfer(const ScheduledTimerService&s){if(!s.complete())throw std::logic_error("Incomplete timer functional transfer");StateUiDomainTransfer out;if(s.kind()==ScheduledTimerService::Kind::Arm)out.presentation=stateUiDomainBindings::word(s.presentation());else if(s.summary().callbackCompleted){out=scheduledTimerBindings::callback(s);out.expression.mask&=0xffff0000u;out.expression.value&=0xffff0000u;out.presentation={};}return out;}
}
